This section contains the contents of the repository's files.import { Redirect } from 'expo-router';
import { ActivityIndicator, View } from 'react-native';
import * as Linking from 'expo-linking';
import { EmergencyEntryLink } from '@/components/emergency-entry-link';
import { ThemedText } from '@/components/themed-text';
import { useAuth } from '@/hooks/use-auth';
import { useTheme } from '@/hooks/use-theme';
import { nativeCallbackPending, setupDestination } from '@/lib/setup-navigation';

export default function RootIndexRedirect() {
  const { session, isGuest, signedOutEntry, isPasswordRecovery, setupRoute, setup, isLoading, restorationError } = useAuth();
  // A cold-started Google callback is handed to /auth/callback by the root navigator;
  // redirecting from here first would drop it on the signed-out entry screen.
  const nativeUrl = Linking.useLinkingURL();
  const theme = useTheme();
  if (restorationError || nativeCallbackPending(nativeUrl)) return null;
  // Shown once the splash lifts during a slow restoration: emergency routes stay reachable.
  if (isLoading) {
    return (
      <View style={{ flex: 1, justifyContent: 'center', alignItems: 'center', gap: 16, backgroundColor: theme.background }}>
        <ActivityIndicator color={theme.primary} />
        <ThemedText accessibilityLiveRegion="polite">Restoring your session…</ThemedText>
        <EmergencyEntryLink style={{ alignSelf: 'stretch' }} />
      </View>
    );
  }
  if (isPasswordRecovery) return <Redirect href="/(auth)/forgot-password" />;
  if (session) {
    return <Redirect href={setupDestination(setupRoute, setup)} />;
  }
  return <Redirect href={isGuest ? '/home' : signedOutEntry ? '/(auth)/login' : '/(auth)/auth-choice'} />;
}import { useRouter } from 'expo-router';
import { Alert, Pressable, StyleSheet } from 'react-native';

import { ThemedText } from '@/components/themed-text';
import { useAuth } from '@/hooks/use-auth';
import { useTheme } from '@/hooks/use-theme';
import { authSetupRequests } from '@/lib/setup-request';

export function GuestBrowseButton({ disabled = false }: { disabled?: boolean }) {
  const router = useRouter();
  const { setGuest } = useAuth();
  const theme = useTheme();
  return (
    <Pressable
      disabled={disabled}
      accessibilityRole="button"
      accessibilityState={{ disabled }}
      accessibilityHint="Browse public updates. You can log in or create an account later."
      style={({ pressed }) => [styles.action, { opacity: disabled ? 0.5 : pressed ? 0.6 : 1 }]}
      onPress={() => {
        if (authSetupRequests.busy) {
          Alert.alert('Please wait', 'An account request is still finishing. Please wait before browsing as a guest.');
          return;
        }
        setGuest(true);
        router.replace('/home');
      }}>
      <ThemedText style={[styles.label, { color: theme.textSecondary }]}>Browse as guest</ThemedText>
    </Pressable>
  );
}

const styles = StyleSheet.create({
  action: { minHeight: 48, alignSelf: 'center', justifyContent: 'center', paddingHorizontal: 20, paddingVertical: 12 },
  label: { fontSize: 14, lineHeight: 22, fontWeight: '600', textAlign: 'center', textDecorationLine: 'underline' },
});// Opt-in identity for local Phase 2 development-device qualification.
// app.json remains the source of the application's normal configuration.
module.exports = ({ config }) => {
  if (process.env.BARANGAYAN_PHASE2_DEV_BUILD !== '1') return config;
  return {
    ...config,
    android: { ...config.android, package: 'com.barangayan.resident.dev' },
    plugins: [...(config.plugins ?? []), ['expo-dev-client', { launchMode: 'most-recent' }]],
  };
};// Metro config for the npm-workspaces monorepo.
// Metro's default config only watches apps/resident-android-mobile, so it can't resolve
// @barangayan/shared out of the box — this is the fix (see the plan's
// "Pre-Development Technical Risk Mitigations").
const { getDefaultConfig } = require('expo/metro-config');
const path = require('path');

const projectRoot = __dirname;
const workspaceRoot = path.resolve(projectRoot, '../..');

const config = getDefaultConfig(projectRoot);

config.watchFolders = [workspaceRoot];
config.resolver.nodeModulesPaths = [
  path.resolve(projectRoot, 'node_modules'),
  path.resolve(workspaceRoot, 'node_modules'),
];
config.resolver.disableHierarchicalLookup = true;

// Local verification tools and web build caches are not mobile source. Watching
// them can stall Metro while web previews/builds write thousands of generated files.
// The file watcher matches these against forward-slash paths even on Windows, so the
// root and separators must accept both `\` and `/`, and directory patterns must also
// match the bare directory path (no trailing separator) to stop the watcher walking in.
const escapedWorkspaceRoot = workspaceRoot
  .split(/[\\/]/)
  .map((segment) => segment.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'))
  .join('[\\\\/]');
const existingBlockList = config.resolver.blockList;
config.resolver.blockList = [
  ...(Array.isArray(existingBlockList) ? existingBlockList : existingBlockList ? [existingBlockList] : []),
  // Other tools create and delete short-lived refs under .git; if one vanishes while
  // the fallback (non-Watchman) watcher is attaching, Metro crashes with ENOENT.
  /[\\/]\.git(?:[\\/]|$)/,
  new RegExp(`^${escapedWorkspaceRoot}[\\\\/]dist(?:[\\\\/]|$)`),
  // Root-level scratch, test output and agent worktrees. Without Watchman the fallback
  // watcher walks every directory under watchFolders and gives up after 240s; these
  // held ~85k of the repo's directories (a stray Gradle cache in .expo alone ~62k).
  new RegExp(
    `^${escapedWorkspaceRoot}[\\\\/](?:\\.expo|\\.scratch|\\.claude|\\.kilo|\\.aider-desk|tmp|plans|output|screen records|repomix output files)(?:[\\\\/]|$)`,
  ),
  new RegExp(`^${escapedWorkspaceRoot}[\\\\/]apps[\\\\/][^\\\\/]+[\\\\/](?:\\.next(?:-[^\\\\/]+)?|dist)(?:[\\\\/]|$)`),
];

// `disableHierarchicalLookup` stops Metro from walking nested node_modules, so it
// only sees the hoisted `entities@4` at the workspace root — which dropped the old
// `lib/maps/*.json` layout that `markdown-it@10` (pulled in by
// react-native-markdown-display) still `require`s. Redirect that legacy subpath to
// markdown-it's own nested `entities@2` copy, leaving entities@4 consumers untouched.
const defaultResolveRequest = config.resolver.resolveRequest;
config.resolver.resolveRequest = (context, moduleName, platform) => {
  if (moduleName.startsWith('entities/lib/')) {
    return {
      type: 'sourceFile',
      filePath: require.resolve(`markdown-it/node_modules/${moduleName}`, {
        paths: [workspaceRoot],
      }),
    };
  }
  return defaultResolveRequest
    ? defaultResolveRequest(context, moduleName, platform)
    : context.resolveRequest(context, moduleName, platform);
};

module.exports = config;
